export function WorkQueue({
  queueName = "{{queueName}}",
  filter = "{{filter}}",
  accent = "{{accent}}",
  showCount = {{showCount}},
}) {
  const rows = [
    { id: "PR #218 review", owner: "mine" },
    { id: "PR #219 review", owner: "unassigned" },
    { id: "PR #220 review", owner: "mine" },
  ].filter((r) => filter === "all" || r.owner === filter);
  const counts = { all: 3, mine: 2, unassigned: 1 };
  return (
    <div style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 16, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 10px", fontWeight: 700 }}>{queueName}</p>
      {rows.map((r) => (
        <div key={r.id} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: 8, borderRadius: 6, background: "#ffffff", border: "1px solid #24143014", marginBottom: 6 }}>
          {r.id}
          <span style={{ fontSize: 10, padding: "2px 8px", borderRadius: 999, fontWeight: r.owner === "mine" ? 700 : 400, color: r.owner === "mine" ? "#241430" : "#24143099", background: r.owner === "mine" ? accent : "#24143014" }}>{r.owner}</span>
        </div>
      ))}
      {showCount && <p style={{ margin: "8px 0 0", fontSize: 10, color: "#24143099" }}>{counts[filter]} item{counts[filter] === 1 ? "" : "s"}</p>}
    </div>
  );
}
